{
  "units": [
    {
      "quote": "Material discrepancies between the name recorded on the application, the applicant's evidence of U.S. citizenship/non-citizen U.S. nationality, or the evidence of identity must be documented by submission of one or more of the documents listed in this section",
      "scope_quotes": [],
      "kind": "requirement",
      "meaning": "If there are material discrepancies between the name recorded on the application and either the evidence of U.S. citizenship/non-citizen U.S. nationality or the evidence of identity, the applicant must document them by submitting one or more of the documents specified in this section."
    },
    {
      "quote": "(see an exception for married names in 8 FAM 403.1-4(C))",
      "scope_quotes": [
        "Material discrepancies between the name recorded on the application, the applicant's evidence of U.S. citizenship/non-citizen U.S. nationality, or the evidence of identity must be documented by submission of one or more of the documents listed in this section"
      ],
      "kind": "exception",
      "meaning": "An exception to the requirement to document material name discrepancies applies for married names pursuant to 8 FAM 403.1-4(C)."
    },
    {
      "quote": "(a) Name change orders; or",
      "scope_quotes": [
        "Acceptable means of documenting a material name change include (per 22 CFR 51.25):",
        "(1) Court orders or decrees:"
      ],
      "kind": "alternative",
      "meaning": "Under 22 CFR 51.25, court orders or decrees in the form of name change orders are an acceptable means of documenting a material name change."
    },
    {
      "quote": "(b) Divorce decrees;",
      "scope_quotes": [
        "Acceptable means of documenting a material name change include (per 22 CFR 51.25):",
        "(1) Court orders or decrees:"
      ],
      "kind": "alternative",
      "meaning": "Under 22 CFR 51.25, court orders or decrees in the form of divorce decrees are an acceptable means of documenting a material name change."
    },
    {
      "quote": "(2) Certificates of naturalization;",
      "scope_quotes": [
        "Acceptable means of documenting a material name change include (per 22 CFR 51.25):"
      ],
      "kind": "alternative",
      "meaning": "Under 22 CFR 51.25, certificates of naturalization constitute an acceptable means of documenting a material name change."
    },
    {
      "quote": "(3) Marriage certificates;",
      "scope_quotes": [
        "Acceptable means of documenting a material name change include (per 22 CFR 51.25):"
      ],
      "kind": "alternative",
      "meaning": "Under 22 CFR 51.25, marriage certificates constitute an acceptable means of documenting a material name change."
    },
    {
      "quote": "(4) Documentation demonstrating change of name by operation of state law; or",
      "scope_quotes": [
        "Acceptable means of documenting a material name change include (per 22 CFR 51.25):"
      ],
      "kind": "alternative",
      "meaning": "Under 22 CFR 51.25, documentation showing a name change occurred by operation of state law constitutes an acceptable means of documenting a material name change."
    },
    {
      "quote": "(5) Documentation of customary usage.",
      "scope_quotes": [
        "Acceptable means of documenting a material name change include (per 22 CFR 51.25):"
      ],
      "kind": "alternative",
      "meaning": "Under 22 CFR 51.25, documentation demonstrating customary usage constitutes an acceptable means of documenting a material name change."
    }
  ]
}
